/**
 * Attribute helpers for the ezoe editor HTML dialect.
 *
 * Every attribute ezoe writes is kept verbatim: the well known ones as named Tiptap attributes (so the UI can read
 * and change them), everything else in one catch-all attribute `extraAttrs`, so unknown classes, custom attributes
 * and attributes of future ezoe versions survive the editor untouched.
 *
 * @license GPL-2.0-or-later
 */
/**
 * Nodes of the ezoe editor HTML dialect (what eZOEXMLInput::inputXML() writes and eZOEInputParser reads).
 * See doc/content-mapping.md for the full table ezxml <-> ezoe HTML <-> Tiptap.
 *
 * @license GPL-2.0-or-later
 */
/**
 * Marks of the ezoe editor HTML dialect.
 *
 *   ezxml <strong>                    <strong>                        bold
 *   ezxml <emphasize>                 <em>                            italic
 *   ezxml <link>                      <a href ...>                    link
 *   ezxml <custom name="sub|sup">     <sub> / <sup>                   subscript / superscript
 *   ezxml <custom> (inline)           <span|u class="ezoeItemCustomTag NAME" type="custom">   ezCustomInline
 *
 * The order of the marks in the list returned by ezoeMarks() is their nesting order on output (first = outermost):
 * inline custom tags, emphasize, strong, sub, sup, link. Formatting usually spans more than a link inside it
 * ("<emphasize>Credit: <link>name</link></emphasize>"), so the link is innermost and the formatting is not split
 * around it (Tiptap orders marks by priority: custom 101, formatting 100, link 50).
 *
 * @license GPL-2.0-or-later
 */
/**
 * Tables of the ezoe editor HTML dialect, built on @tiptap/extension-table (commands, prosemirror-tables).
 *
 *   ezxml <table class border width align custom:*>  <table customattributes width border align class style><tbody>
 *   ezxml <tr class custom:*>                         <tr customattributes class style>
 *   ezxml <td|th class align xhtml:width xhtml:colspan xhtml:rowspan custom:*>
 *                                                     <td|th customattributes class width colspan rowspan align style>
 *
 * Tiptap's own output (a <colgroup>, a min-width style, text-align styles, colspan="1") is not used: the parser
 * would turn the styles into attributes. Everything ezoe writes is kept verbatim; colspan/rowspan of 1 are left out
 * as ezoe does.
 *
 * @license GPL-2.0-or-later
 */
/**
 * Post-processing of the HTML Tiptap serialises, so that it is the HTML ezoe's TinyMCE posts and eZOEInputParser
 * expects (the same clean-ups ezoe's own plugins make when the form is saved):
 *
 *  - an empty paragraph is <p><br></p> (TinyMCE's form; the parser keeps it as an empty paragraph)
 *  - a list item with a single paragraph without attributes is written without the <p> (eZOEXMLInput writes it so)
 *  - the preview inside <div>/<span> embeds becomes the text "ezembed" (ezembed plugin, issue 18264)
 *  - the ezoeAlign<align> helper class of image embeds is removed (ezembed plugin, EZP-22487)
 *  - line breaks in a <pre> are <br> (eZOEXMLInput writes them so; the parser reads both)
 *
 * @license GPL-2.0-or-later
 */
/**
 * The ezoe editor HTML dialect as a Tiptap schema.
 *
 * Tiptap edits exactly the HTML ezoe's TinyMCE edits: eZOEXMLInput::inputXML() makes it from the stored ezxml, the
 * form posts it, eZOEInputParser turns it back into ezxml. Nothing on the server changes.
 *
 *   import { ezoeExtensions, fromEditorHTML, toEditorHTML } from './schema/index.js';
 *
 *   const editor = new Editor( { extensions: [ ...ezoeExtensions(), UndoRedo, ... ],
 *                                content: fromEditorHTML( textarea.value ) } );
 *   form.onsubmit = () => { textarea.value = toEditorHTML( editor ); };
 *
 * editor.getHTML() is NOT what is posted: it keeps embed previews and lacks the clean-ups of toEditorHTML().
 *
 * @license GPL-2.0-or-later
 */
